starter.css:
:root { --accent: #087565; }
* { box-sizing: border-box; }
body { margin: 0; background: #faf7ed; color: #193f38; font: 15px/1.6 system-ui; }
main { max-width: 560px; margin: auto; padding: 24px; }
h1 { font: 34px/1.15 Georgia, serif; margin: 14px 0; }
h2 { font-size: 18px; }
.eyebrow { font-size: 10px; letter-spacing: .12em; color: var(--accent); }
article, .cart { background: white; padding: 20px; border: 1px solid #dde5d6; border-radius: 14px; margin: 20px 0; }
.dish { display: grid; place-items: center; height: 80px; background: #f4dc9d; font-size: 45px; border-radius: 9px; }
button { display: block; width: 100%; background: var(--accent); color: white; border: 0; border-radius: 9px; padding: 13px; margin-top: 12px; cursor: pointer; font: inherit; }
input { display: block; width: 100%; padding: 10px; border: 1px solid #a8bfb1; border-radius: 6px; font: inherit; }
small { color: #60766c; }
#message { font-weight: 650; }

starter.js:
// Keep money in integer cents. This is a browser practice model.
const priceCents = 1299;
let quantity = 0;
const money = cents => '$' + (cents / 100).toFixed(2);
function updateCart() {
  document.querySelector('#quantity').textContent = quantity;
  document.querySelector('#total').textContent = money(priceCents * quantity);
}
document.querySelector('#add').addEventListener('click', () => {
  quantity += 1;
  updateCart();
  console.log('Cart now has ' + quantity + ' item(s).');
});
document.querySelector('#checkout').addEventListener('click', () => {
  const table = document.querySelector('#table').value.trim();
  const message = document.querySelector('#message');
  if (quantity < 1) {
    message.textContent = 'Add an item first.';
    return;
  }
  if (!table) {
    message.textContent = 'Please enter a table number.';
    return;
  }
  message.textContent = 'Practice order ready for Table ' + table + '.';
  console.log('Practice order prepared. Nothing was sent to a restaurant.');
});
updateCart();
